#!/bin/zsh
# 视频素材保留画面：素材详情里看画面、设置里的保留规则和占用、导入时可勾选保留画面。
cd "$(dirname "$0")"
gen() {
  local name=$1; local prompt=$2
  [ -f "$name.png" ] && return
  local t0=$(date +%s)
  codex exec --skip-git-repo-check --ephemeral -c 'model_reasoning_effort="low"' -C "$PWD" -s workspace-write \
    "请使用内置的 image_gen 工具生成一张高保真 UI 设计稿（像设计师在 Figma 里做的最终稿截图，正视图、不要透视、纯浅灰背景上只放这一个窗口）：$prompt 生成后把最终图片复制到当前目录，命名为 $name.png，然后只回复文件名。" < /dev/null > "$name.log" 2>&1
  echo "$name $(( $(date +%s) - t0 ))s $([ -f $name.png ] && echo ok || echo FAIL)"
}
S="这是 macOS 桌面应用「豆仓」（把录音和视频素材转成文字、整理成纪要）。设计语言：苹果 macOS 最新系统的风格加乔纳森·艾维式的克制——圆角卡片、细分隔线、说明是小号灰字、对齐严谨、留白舒服。配色严格限定：暖灰纸色背景（#FAF9F7）、卡片纯白、深暖灰文字（#1C1917）、唯一强调色玫瑰红（#F43F5E，用在主按钮、开关、选中的分段）；绝对不要蓝色、紫色、青色。视频画面里是虚构人物或风景，不要任何真实品牌 Logo。界面文字全部是简体中文，字体像苹方，清晰可读、没有乱码。"
gen ui_video_detail "【素材详情页，带视频画面】一个 macOS 窗口宽约 1200：左边是窄侧栏（小仓鼠头像「豆仓」、开始录音按钮、总览/录音/素材/知识库，「素材」选中），中间是素材列表（几行卡片，每行左侧一个小的竖版视频缩略图带右下角时长角标，标题、平台 · 作者 · 时长），右边是详情。详情顶部：灰色小胶囊「抖音」、日期、时长 1:12；大标题「三分钟讲清楚复利」；下面一张卡片：左边是一个竖版 9:16 的视频画面（约 200×356，一位虚构的年轻女性在书桌前对着镜头讲话，画面下方叠一行白色字幕），右边竖排信息：「抖音 · @小林说财经」「画面 720p · 9.6 MB」，两个小按钮「打开原链接」「删掉画面」，再下面小灰字「删掉画面后声音和文字稿都还在。」。卡片下面是分段「纪要 / 文字稿 / 改写」（文字稿选中），文字稿逐句排列，当前正在播的那句玫瑰红高亮。窗口最底部是悬浮的播放条：玫瑰红圆形播放按钮、波形时间轴（已播部分玫瑰红）、0:23 / 1:12、倍速 1×。$S" &
gen ui_video_settings "【设置窗口「通用」页签】窗口宽约 680，顶部一排居中的页签「通用」「语音输入」「模型」「词库」「连接」，「通用」选中为玫瑰红。内容里一张卡片「视频素材」：第一行「保留画面」右边三段分段选择「短视频」「都保留」「都不保留」（「短视频」选中）；下面小灰字「从链接导入视频时，5 分钟以内的保留 720p 画面，更长的只留声音。导入时也可以单独勾选。」；第二行「画面占用」右边灰字「186 MB · 12 条素材」和一个小按钮「清理画面…」；下面小灰字「清理只删画面，声音、文字稿和纪要都留着。想看画面时也可以打开原链接。」。卡片上下各露出一点别的设置卡片的边缘（「外观」「录完之后」），表示这是页面中间的一段。$S" &
gen ui_video_import "【从链接导入的弹出单】宽约 560。标题「从链接导入」，一个多行输入框里贴着两条链接（一条 youtube.com 的、一条 douyin.com 的，用假的示例地址）。下面是待导入列表两行，每行：平台小胶囊（「YouTube」「抖音」）、标题（「How to Read a Paper · 42:18」「三分钟讲清楚复利 · 1:12」）、右侧一个小复选框「保留画面」——YouTube 那行没勾（旁边小灰字「较长，默认只留声音」），抖音那行勾上（玫瑰红）。底部小灰字「只导入你有权保存的公开内容。」，右下角按钮「取消」和玫瑰红实心「导入 2 条」。$S" &
wait
